async function fetchCanvasJson(path) {
	const res = await fetch(path, {
		method: "GET",
		credentials: "same-origin",
		headers: {
			"x-recruitment-request": "1",
			Accept: "application/json"
		}
	});
	if (!res.ok) throw new Error("CANVAS_FETCH_FAILED");
	return res.json();
}
